// Aniimo game pack — adapter over data/aniimo.ts (generated by
// scripts/build-aniimo.mjs from the sources in data/source/aniimo/).
//
// Aniimo has no breeding: the graph is evolution only. Edges are
// single-input, typed "evolve", and carry their conditions (level gate,
// evolution stone / item, deed, talent, ...) as EdgeCondition entries.
// Twining is a single-creature sync mechanic in this game — there is no
// pairing matrix to model (see data/source/aniimo/SOURCING.md).

import { ANIIMO_CREATURES, ANIIMO_EDGES } from "../../../data/aniimo";
import type { GamePack, TransformEdge } from "../types";

const withIncoming = new Set(ANIIMO_EDGES.map((e) => e.to));

export const aniimoPack: GamePack = {
  gameId: "aniimo",
  gameName: "Aniimo",
  dataVersion:
    "Launch roster (Sep 2026) · wiki snapshot 2026-09-02 + conditions checked 2026-10-23",
  creatures: ANIIMO_CREATURES.map((c) => ({
    id: c.name,
    name: c.name,
    gameId: "aniimo",
  })),
  edges: ANIIMO_EDGES.map(
    (e): TransformEdge => ({
      kind: "evolve",
      from: [e.from],
      to: e.to,
      conditions: [
        ...e.conditions.map((c) => ({
          kind: c.kind,
          label: c.label,
          value: c.value,
        })),
        // Honesty flag from the data layer: these evolutions are real, but
        // no source publishes their conditions yet. Surfaced in the UI as a
        // visible "not yet verified" chip, never silently omitted.
        ...(e.conditionsVerified
          ? []
          : [
              {
                kind: "unverified",
                label:
                  "Conditions not yet verified — this evolution is confirmed, its requirements are still being sourced",
              },
            ]),
      ],
    }),
  ),
  isBaseCreature: (c) => !withIncoming.has(c.id),
  terms: { combine: "evolve", creature: "Aniimo", creatures: "Aniimo" },
};
